def syms(M):
    M=np.array(M); out=set()
    cur=M
    for _ in range(4):
        for M2 in (cur, cur.T):
            for f_ in (False,True):
                m=(M2 if f_ else M2[::-1]).tolist()
                n=norm(m)
                out.add(tuple(map(tuple,n)))
        cur=np.rot90(cur)
    return out
def components(mask):
    seen=set(); comps=[]
    H,W=len(mask),len(mask[0])
    for i in range(H):
        for j in range(W):
            if mask[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<H and 0<=xx<W and mask[yy][xx] and (yy,xx) not in seen:
                                seen.add((yy,xx)); st.append((yy,xx))
                comps.append(comp)
    return comps
